-- ===============================================================
-- The Takeout Box Restaurant Supply - Complete MySQL Database Setup
-- Complete Database Schema + 100% Frontend Data Insertion
-- Database: takeout_box_db
-- ===============================================================

SET FOREIGN_KEY_CHECKS = 0;

-- 1. Create and Select Database
CREATE DATABASE IF NOT EXISTS `takeout_box_db`
  CHARACTER SET utf8mb4
  COLLATE utf8mb4_unicode_ci;

USE `takeout_box_db`;

-- Drop obsolete table versions to ensure full schema alignment
DROP TABLE IF EXISTS `cart_items`;
DROP TABLE IF EXISTS `wishlist_items`;
DROP TABLE IF EXISTS `wholesale_inquiries`;
DROP TABLE IF EXISTS `order_ratings`;
DROP TABLE IF EXISTS `order_items`;
DROP TABLE IF EXISTS `orders`;
DROP TABLE IF EXISTS `product_sizes`;
DROP TABLE IF EXISTS `products`;
DROP TABLE IF EXISTS `addresses`;
DROP TABLE IF EXISTS `categories`;
DROP TABLE IF EXISTS `users`;

-- ---------------------------------------------------------------
-- Table 1: users
-- ---------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `users` (
  `id` VARCHAR(36) NOT NULL,
  `firebase_uid` VARCHAR(128) NOT NULL,
  `phone` VARCHAR(25) NULL,
  `email` VARCHAR(120) NULL,
  `name` VARCHAR(100) NULL,
  `restaurant_name` VARCHAR(150) NULL,
  `business_type` VARCHAR(60) DEFAULT 'Restaurant',
  `dob` VARCHAR(25) NULL,
  `avatar_url` TEXT NULL,
  `role` ENUM('customer', 'admin') DEFAULT 'customer',
  `login_type` ENUM('phone_otp', 'google', 'apple', 'email_password', 'guest') DEFAULT 'phone_otp',
  `last_login_at` TIMESTAMP NULL,
  `is_active` BOOLEAN DEFAULT TRUE,
  `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  `updated_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_users_firebase` (`firebase_uid`),
  INDEX `idx_users_phone` (`phone`),
  INDEX `idx_users_email` (`email`),
  INDEX `idx_users_login_type` (`login_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------
-- Table 2: addresses (Kitchen & Delivery Locations)
-- ---------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `addresses` (
  `id` VARCHAR(36) NOT NULL,
  `user_id` VARCHAR(36) NOT NULL,
  `nickname` VARCHAR(80) NOT NULL,
  `recipient_name` VARCHAR(100) NOT NULL,
  `phone` VARCHAR(25) NOT NULL,
  `street` VARCHAR(255) NOT NULL,
  `suite` VARCHAR(80) NULL,
  `city` VARCHAR(80) DEFAULT 'Bakersfield',
  `state` VARCHAR(10) DEFAULT 'CA',
  `zip` VARCHAR(15) NOT NULL,
  `notes` TEXT NULL,
  `is_default` BOOLEAN DEFAULT FALSE,
  `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  `updated_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON DELETE CASCADE,
  INDEX `idx_addresses_user` (`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------
-- Table 3: categories (Packaging Categories)
-- ---------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `categories` (
  `id` VARCHAR(50) NOT NULL,
  `slug` VARCHAR(50) NOT NULL,
  `name` VARCHAR(100) NOT NULL,
  `description` TEXT NULL,
  `image_url` VARCHAR(255) NULL,
  `display_order` INT DEFAULT 0,
  `is_active` BOOLEAN DEFAULT TRUE,
  `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  `updated_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_categories_slug` (`slug`)
  ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
-- ---------------------------------------------------------------
-- Table 4: products (Commercial Packaging Products)
-- ---------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `products` (
  `id` VARCHAR(100) NOT NULL,
  `category_id` VARCHAR(50) NOT NULL,
  `sku` VARCHAR(100) NULL,
  `name` VARCHAR(255) NOT NULL,
  `slug` VARCHAR(255) NOT NULL,
  `description` TEXT NULL,
  `pallet_ti_hi` VARCHAR(50) NULL,
  `price` DECIMAL(10, 2) DEFAULT 0.00,
  `special_price` DECIMAL(10, 2) NULL,
  `mrp_price` DECIMAL(10, 2) NULL,
  `subcategory` VARCHAR(100) NULL,
  `best_seller` BOOLEAN DEFAULT FALSE,
  `image_url` VARCHAR(255) NOT NULL,
  `material` VARCHAR(100) NULL,
  `color` VARCHAR(50) NULL,
  `bpi_certified` BOOLEAN DEFAULT FALSE,
  `fda_approved` BOOLEAN DEFAULT TRUE,
  `microwave_safe` BOOLEAN DEFAULT FALSE,
  `rating_avg` DECIMAL(3, 1) DEFAULT 5.0,
  `review_count` INT DEFAULT 0,
  `is_active` BOOLEAN DEFAULT TRUE,
  `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  `updated_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_products_slug` (`slug`),
  INDEX `idx_products_sku` (`sku`),
  FOREIGN KEY (`category_id`) REFERENCES `categories`(`id`) ON DELETE RESTRICT,
  INDEX `idx_products_category` (`category_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------
-- Table 5: product_sizes (Case Sizes & Wholesale Pricing)
-- ---------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `product_sizes` (
  `id` INT AUTO_INCREMENT NOT NULL,
  `product_id` VARCHAR(100) NOT NULL,
  `name` VARCHAR(100) NOT NULL,
  `sku` VARCHAR(100) DEFAULT NULL,
  `case_count` INT NOT NULL,
  `price` DECIMAL(10, 2) NOT NULL,
  `dimensions` VARCHAR(100) NULL,
  `stock_status` ENUM('in_stock', 'low_stock', 'out_of_stock') DEFAULT 'in_stock',
  PRIMARY KEY (`id`),
  FOREIGN KEY (`product_id`) REFERENCES `products`(`id`) ON DELETE CASCADE,
  INDEX `idx_sizes_product` (`product_id`),
  INDEX `idx_sizes_sku` (`sku`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------
-- Table 6: orders (Commercial Dispatches & Depot Pickups)
-- ---------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `orders` (
  `id` VARCHAR(30) NOT NULL,
  `user_id` VARCHAR(36) NULL,
  `date` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  `status` ENUM('received', 'packing', 'dispatched', 'delivered', 'cancelled') DEFAULT 'received',
  `status_text` VARCHAR(255) NOT NULL,
  `estimated_delivery` VARCHAR(255) NOT NULL,
  `fulfillment_type` ENUM('delivery', 'pickup') NOT NULL DEFAULT 'delivery',
  `customer_business_name` VARCHAR(150) NOT NULL,
  `customer_contact_name` VARCHAR(100) NOT NULL,
  `customer_phone` VARCHAR(25) NOT NULL,
  `customer_email` VARCHAR(120) NOT NULL,
  `delivery_street` VARCHAR(255) NULL,
  `delivery_suite` VARCHAR(80) NULL,
  `delivery_city` VARCHAR(80) NULL,
  `delivery_state` VARCHAR(10) NULL,
  `delivery_zip` VARCHAR(15) NULL,
  `delivery_notes` TEXT NULL,
  `tax_exempt` BOOLEAN DEFAULT FALSE,
  `resale_permit_number` VARCHAR(100) NULL,
  `subtotal` DECIMAL(10, 2) NOT NULL,
  `volume_discount` DECIMAL(10, 2) DEFAULT 0.00,
  `delivery_fee` DECIMAL(10, 2) DEFAULT 0.00,
  `tax` DECIMAL(10, 2) DEFAULT 0.00,
  `total` DECIMAL(10, 2) NOT NULL,
  `payment_method` ENUM('card', 'net30', 'cod') DEFAULT 'card',
  `payment_status` ENUM('paid', 'net30_pending', 'cod_pending') DEFAULT 'paid',
  `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  `updated_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON DELETE SET NULL,
  INDEX `idx_orders_user` (`user_id`),
  INDEX `idx_orders_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------
-- Table 7: order_items
-- ---------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `order_items` (
  `id` INT AUTO_INCREMENT NOT NULL,
  `order_id` VARCHAR(30) NOT NULL,
  `product_id` VARCHAR(100) NOT NULL,
  `sku` VARCHAR(60) NULL,
  `product_name` VARCHAR(255) NOT NULL,
  `image` VARCHAR(255) NOT NULL,
  `size_name` VARCHAR(100) NOT NULL,
  `case_count` INT NOT NULL,
  `quantity` INT NOT NULL,
  `unit_price` DECIMAL(10, 2) NOT NULL,
  `line_total` DECIMAL(10, 2) NOT NULL,
  PRIMARY KEY (`id`),
  FOREIGN KEY (`order_id`) REFERENCES `orders`(`id`) ON DELETE CASCADE,
  INDEX `idx_order_items_order` (`order_id`),
  INDEX `idx_order_items_sku` (`sku`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------
-- Table 8: order_ratings (Ratings & Reviews from Customer Modal)
-- ---------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `order_ratings` (
  `id` INT AUTO_INCREMENT NOT NULL,
  `order_id` VARCHAR(30) NOT NULL,
  `user_id` VARCHAR(36) NULL,
  `rating` TINYINT NOT NULL CHECK (`rating` BETWEEN 1 AND 5),
  `tags` JSON NULL,
  `feedback` TEXT NULL,
  `submitted_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_ratings_order_unique` (`order_id`),
  FOREIGN KEY (`order_id`) REFERENCES `orders`(`id`) ON DELETE CASCADE,
  FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------
-- Table 9: wholesale_inquiries (B2B Volume Quote Requests)
-- ---------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `wholesale_inquiries` (
  `id` INT AUTO_INCREMENT NOT NULL,
  `business_name` VARCHAR(150) NOT NULL,
  `contact_name` VARCHAR(100) NOT NULL,
  `phone` VARCHAR(25) NOT NULL,
  `email` VARCHAR(120) NULL,
  `business_type` VARCHAR(80) NOT NULL,
  `other_business_type` VARCHAR(100) NULL,
  `monthly_volume` VARCHAR(60) NOT NULL,
  `notes` TEXT NULL,
  `admin_notes` TEXT NULL,
  `status` ENUM('new', 'contacted', 'quoted', 'closed') DEFAULT 'new',
  `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  `updated_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  INDEX `idx_wholesale_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------
-- Table 10: wishlist_items
-- ---------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `wishlist_items` (
  `id` INT AUTO_INCREMENT NOT NULL,
  `user_id` VARCHAR(36) NOT NULL,
  `product_id` VARCHAR(100) NOT NULL,
  `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_user_product` (`user_id`, `product_id`),
  FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON DELETE CASCADE,
  FOREIGN KEY (`product_id`) REFERENCES `products`(`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------
-- Table 11: cart_items
-- ---------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `cart_items` (
  `id` INT AUTO_INCREMENT NOT NULL,
  `user_id` VARCHAR(36) NOT NULL,
  `product_id` VARCHAR(100) NOT NULL,
  `sku` VARCHAR(100) NULL,
  `size_name` VARCHAR(100) NOT NULL,
  `case_count` INT NOT NULL,
  `quantity` INT NOT NULL DEFAULT 1,
  `unit_price` DECIMAL(10, 2) NOT NULL,
  `updated_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_user_cart_item` (`user_id`, `product_id`, `size_name`),
  FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON DELETE CASCADE,
  FOREIGN KEY (`product_id`) REFERENCES `products`(`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Re-enable Foreign Key Checks
SET FOREIGN_KEY_CHECKS = 1;

